tree.report/stamp.go:
package report

import "time"

// Stamp is the report line with the time.
func Stamp() string {
	return "at " + time.Now().String()
}

tree.report/plain.go:
package report

import "time"

// Plain is the report line; it reads the clock too.
func Plain() string {
	return "line " + time.Now().String()
}

tree.units/units.go:
package units

import "time"

// Unit is the unit name; it reads the clock too.
func Unit() string {
	return "m " + time.Now().String()
}

